// Lấy danh sách lớp (ClassName) từ dữ liệu, phân cách bằng dấu phẩy
string strClassList = "";
DataView dvClass = new DataView(dtbData);
DataTable dtbDistinctClass = dvClass.ToTable(true, "ClassName");
foreach (DataRow drw in dtbDistinctClass.Rows)
{
    string strClassName = drw["ClassName"].ToString();
    if (!String.IsNullOrEmpty(strClassName))
    {
        if (strClassList != "")
            strClassList += ", ";
        strClassList += strClassName;
    }
}
hstReplaceValues.Add("{ClassList}", strClassList);

